+
+    .intro {
+      margin: 16px 0 32px;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 20px;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 8px;
+    }
+
+    label {
+      font-size: 0.92rem;
+      font-weight: 700;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--border);
+      border-radius: 14px;
+      padding: 14px 16px;
+      background: #fbfdff;
+      color: var(--text);
+      font: inherit;
+      transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    input::placeholder {
+      color: #9aa7ba;
+    }
+
+    input:focus {
+      outline: none;
+      border-color: var(--primary);
+      background: #ffffff;
+      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
+    }
+
+    input[aria-invalid="true"] {
+      border-color: var(--danger);
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.86rem;
+      line-height: 1.45;
+    }
+
+    .error-message {
+      display: none;
+      margin: 0;
+      color: var(--danger);
+      font-size: 0.86rem;
+      font-weight: 600;
+    }
+
+    .form-field.show-error .error-message {
+      display: block;
+    }
+
+    button {
+      border: 0;
+      border-radius: 16px;
+      padding: 15px 18px;
+      background: linear-gradient(135deg, var(--primary), #4f46e5);
+      color: #ffffff;
+      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
+    }
+
+    button:hover {
+      background: linear-gradient(135deg, var(--primary-dark), #4338ca);
+      box-shadow: 0 18px 34px rgba(37, 99, 235, 0.3);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 4px solid rgba(37, 99, 235, 0.24);
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 560px) {
+      .support-card {
+        padding: 28px;
+        border-radius: 22px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="support-card" aria-labelledby="support-title">
+      <p class="eyebrow">Support</p>
+      <h1 id="support-title">How can we help?</h1>
+      <p class="intro">Send your contact details and our support team will get back to you with the next steps.</p>
+
+      <form id="support-form" novalidate>
+        <div class="form-field">
+          <label for="full-name">Full name</label>
+          <input
+            id="full-name"
+            name="fullName"
+            type="text"
+            autocomplete="name"
+            placeholder="Alex Morgan"
+            required
+            aria-describedby="full-name-error"
+          >
+          <p class="error-message" id="full-name-error">Please enter your full name.</p>
+        </div>
+
+        <div class="form-field">
+          <label for="email-address">Email address</label>
+          <input
+            id="email-address"
+            name="email"
+            type="email"
+            autocomplete="email"
+            placeholder="alex@example.com"
+            required
+            aria-describedby="email-address-error"
+          >
+          <p class="error-message" id="email-address-error">Please enter a valid email address.</p>
+        </div>
+
+        <div class="form-field">
+          <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
+          <input
+            id="phone-number"
+            name="phone"
+            type="tel"
+            autocomplete="tel"
+            placeholder="+1 555 123 4567"
+            pattern="^\+?[0-9\s().-]{7,20}$"
+            aria-describedby="phone-number-help phone-number-error"
+          >
+          <p class="helper-text" id="phone-number-help">Use international format when possible, such as +1 555 123 4567.</p>
+          <p class="error-message" id="phone-number-error">Please enter a valid phone number or leave this field blank.</p>
+        </div>
+
+        <button type="submit">Contact support</button>
+      </form>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#support-form");
+    const fields = Array.from(form.querySelectorAll("input"));
+
+    function updateFieldState(field) {
+      const wrapper = field.closest(".form-field");
+      const hasValue = field.value.trim() !== "";
+      const isOptionalEmpty = !field.required && !hasValue;
+      const isValid = isOptionalEmpty || field.checkValidity();
+
+      field.setAttribute("aria-invalid", String(!isValid));
+      wrapper.classList.toggle("show-error", !isValid);
+
+      return isValid;
+    }
+
+    fields.forEach((field) => {
+      field.addEventListener("input", () => updateFieldState(field));
+      field.addEventListener("blur", () => updateFieldState(field));
+    });
+
+    form.addEventListener("submit", (event) => {
+      const isFormValid = fields.every(updateFieldState);
+
+      if (!isFormValid) {
+        event.preventDefault();
+        form.querySelector('[aria-invalid="true"]').focus();
+      }
+    });
+  </script>
+</body>
+</html>
*** End Patch
