            autocomplete="email"
            placeholder="alex@example.com"
            required
            data-error-message="Please enter a valid email address."
          >
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number <span aria-hidden="true">(optional)</span></label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            placeholder="+1 555 123 4567"
            pattern="^\+?[0-9\s().-]{7,20}$"
            aria-describedby="phone-number-help"
            data-error-message="Please enter a valid phone number or leave this field blank."
          >
          <p class="helper-text" id="phone-number-help">Use international format when possible, such as +1 555 123 4567.</p>
        </div>

        <button type="submit">Contact support</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const fields = Array.from(form.querySelectorAll("input"));

    function updateFieldState(field) {
      const wrapper = field.closest(".form-field");
      const hasValue = field.value.trim() !== "";
      const isOptionalEmpty = !field.required && !hasValue;
      const isValid = isOptionalEmpty || field.checkValidity();
      let errorMessage = wrapper.querySelector(".error-message");

      if (!isValid && !errorMessage) {
        errorMessage = document.createElement("p");
        errorMessage.className = "error-message";
        errorMessage.id = `${field.id}-error`;
        errorMessage.textContent = field.dataset.errorMessage;
        wrapper.append(errorMessage);
      }

      field.setAttribute("aria-invalid", String(!isValid));
      if (errorMessage) {
        errorMessage.hidden = isValid;
        field.setAttribute("aria-describedby", getDescriptionIds(field, errorMessage.id));
      }
      wrapper.classList.toggle("show-error", !isValid);

      return isValid;
    }

    function getDescriptionIds(field, errorId) {
      const ids = new Set((field.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
      ids.add(errorId);
      return Array.from(ids).join(" ");
